import type { FilterExpression } from '@wix/sdk-types'
import type {
  WixDataCountOptions,
  WixDataItem,
  WixDataQuerySpec,
} from './types'

/**
 * Options builder for count operations.
 *
 * Use this builder to configure count behavior such as hooks suppression,
 * app-specific options, language, consistency, and filters.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataCountOptionsBuilder {
  /**
   * Sets whether to suppress count hooks.
   *
   * When `true`, the count runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataCountOptionsBuilder
  /**
   * Sets whether to include draft items when counting items.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataCountOptionsBuilder
  /**
   * Sets app-specific options for the count operation.
   */
  withAppOptions(value: Record<string, any>): WixDataCountOptionsBuilder
  /**
   * Sets the language used for the count operation.
   */
  withLanguage(value: string): WixDataCountOptionsBuilder
  /**
   * Sets whether the count uses a consistent read.
   */
  withConsistentRead(value: boolean): WixDataCountOptionsBuilder
  /**
   * Sets the filter used to count matching items.
   */
  withFilter(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataCountOptionsBuilder
  /**
   * Builds the count options object.
   */
  build(): WixDataCountOptions
}

class WixDataCountOptionsBuilderImpl implements WixDataCountOptionsBuilder {
  constructor(private readonly options: WixDataCountOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataCountOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataCountOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withAppOptions(value: Record<string, any>): WixDataCountOptionsBuilder {
    return this.copy({ appOptions: { ...value } })
  }

  withLanguage(value: string): WixDataCountOptionsBuilder {
    return this.copy({ language: value })
  }

  withConsistentRead(value: boolean): WixDataCountOptionsBuilder {
    return this.copy({ consistentRead: value })
  }

  withFilter(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataCountOptionsBuilder {
    return this.copy({ filter: value.filter })
  }

  build(): WixDataCountOptions {
    return {
      ...this.options,
      ...(this.options.appOptions
        ? { appOptions: { ...this.options.appOptions } }
        : {}),
    }
  }

  private copy(options: WixDataCountOptions): WixDataCountOptionsBuilder {
    return new WixDataCountOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new count options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a count options builder"
 * import { items, CountOptionsBuilder } from '@wix/data'
 *
 * const options = CountOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withAppOptions({ key: 'value' })
 *   .withLanguage('en')
 *   .withConsistentRead(true)
 *   .withFilter(Filter('status').eq('active'))
 *   .build()
 *
 * const total = await items.count('myCollection', options)
 * ```
 */
export const CountOptionsBuilder: () => WixDataCountOptionsBuilder = () =>
  new WixDataCountOptionsBuilderImpl()
